values ((select id from public.colleges where slug = 'stanford'), '450 Jane Stanford Way, Stanford, CA 94305', 1885, 'Suburban', 'Stanford sits on 8,180 acres between San Francisco and San Jose, and its scale is the point: seven schools, a teaching hospital and a linear accelerator on one contiguous campus. Undergraduates apply to the university rather than to a major, and most take courses across at least three schools before declaring. The quarter system moves quickly — ten weeks per course — which suits students who like breadth and rewards those who arrive with strong time management.', '5:1', 74, 94, 99, 2037900, '1500–1580', '34–35', '3.95–4.00', true, array['Computer Science', 'Human Biology', 'Engineering', 'Economics', 'Symbolic Systems']::text[], '{"undergrads":7841,"totalStudents":17441,"fullTimeUndergradPct":99,"retentionPct":99,"gender":{"femalePct":50,"malePct":50},"ethnicity":[{"group":"Asian","pct":26},{"group":"White","pct":22},{"group":"Hispanic/Latino","pct":18},{"group":"International","pct":12},{"group":"Two or more races","pct":11},{"group":"Black or African American","pct":7},{"group":"Unknown or other","pct":4}],"source":"IPEDS Fall Enrollment 2024–25 and Common Data Set section B. Percentages are rounded and may not total exactly 100."}'::jsonb, '{"essay":"Required","testing":"Required","subjectTests":"Not accepted","interview":"Conditional","note":"Testing is required again from fall 2026 entry. The alumni interview happens only where a volunteer covers the applicant''s area, and its absence is explicitly not held against a file."}'::jsonb, '[{"band":"Under $30k","priceCents":356000},{"band":"$30k–48k","priceCents":421000},{"band":"$48k–75k","priceCents":894000},{"band":"$75k–110k","priceCents":1842000},{"band":"$110k+","priceCents":3765000}]'::jsonb, 'Common Data Set 2024–25 and IPEDS (fall 2024 enrollment, 2025–26 cost). Deadlines and test policies verified against institution websites.', 'sourced')
