values ((select id from public.colleges where slug = 'mit'), '77 Massachusetts Ave, Cambridge, MA 02139', 1861, 'City', 'MIT runs on a shared first-year core — calculus, physics, chemistry, biology — taken pass/no-record in the fall, which is the institute''s deliberate answer to the transition problem. Roughly 90% of undergraduates do research through UROP, often starting first year. The culture is collaborative rather than cutthroat: problem sets are explicitly designed to be worked in groups, and the difficulty is the shared experience students bond over.', '3:1', 89, 96, 99, 2115000, '1520–1580', '35–36', '3.95–4.00', false, array['Computer Science', 'Mechanical Engineering', 'Mathematics', 'Physics', 'Electrical Engineering']::text[], '{"undergrads":4576,"totalStudents":11876,"fullTimeUndergradPct":99,"retentionPct":99,"gender":{"femalePct":49,"malePct":51},"ethnicity":[{"group":"Asian","pct":34},{"group":"White","pct":24},{"group":"Hispanic/Latino","pct":14},{"group":"International","pct":11},{"group":"Black or African American","pct":9},{"group":"Two or more races","pct":7},{"group":"Unknown or other","pct":1}],"source":"IPEDS Fall Enrollment 2024–25 and Common Data Set section B. Percentages are rounded and may not total exactly 100."}'::jsonb, '{"essay":"Required","testing":"Required","subjectTests":"Not accepted","interview":"Conditional","note":"MIT reads short-answer responses rather than one long essay. Educational Counselor interviews are offered where coverage exists and are not available everywhere."}'::jsonb, '[{"band":"Under $30k","priceCents":287000},{"band":"$30k–48k","priceCents":394000},{"band":"$48k–75k","priceCents":921000},{"band":"$75k–110k","priceCents":1987000},{"band":"$110k+","priceCents":3420000}]'::jsonb, 'Common Data Set 2024–25 and IPEDS (fall 2024 enrollment, 2025–26 cost). Deadlines and test policies verified against institution websites.', 'sourced')
