values ((select id from public.colleges where slug = 'uc-berkeley'), '110 Sproul Hall, Berkeley, CA 94720', 1868, 'City', 'Berkeley is the flagship of the University of California system and the largest research university on this list by undergraduate headcount. Students apply directly to a college — Letters & Science, Engineering, Haas, and others — and switching between them after enrolling ranges from routine to very difficult depending on the target. Class sizes in lower-division courses are large; the counterweight is a research and faculty depth that few institutions anywhere can match.', '19:1', 76, 94, 97, 2183000, '1330–1530', '29–35', '3.86–4.00', false, array['Computer Science', 'Economics', 'Cellular Biology', 'Political Science', 'Data Science']::text[], '{"undergrads":33078,"totalStudents":45878,"fullTimeUndergradPct":96,"retentionPct":97,"gender":{"femalePct":54,"malePct":46},"ethnicity":[{"group":"Asian","pct":37},{"group":"Hispanic/Latino","pct":22},{"group":"White","pct":20},{"group":"International","pct":9},{"group":"Two or more races","pct":6},{"group":"Black or African American","pct":4},{"group":"Unknown or other","pct":2}],"source":"IPEDS Fall Enrollment 2024–25 and Common Data Set section B. Percentages are rounded and may not total exactly 100."}'::jsonb, '{"essay":"Required","testing":"Not accepted","subjectTests":"Not accepted","interview":"Not accepted","note":"Four Personal Insight Questions replace the essay. Berkeley is test blind — submitted scores are not read at all — and the UC system does not interview."}'::jsonb, '[{"band":"Under $30k","priceCents":912000},{"band":"$30k–48k","priceCents":1134000},{"band":"$48k–75k","priceCents":1796000},{"band":"$75k–110k","priceCents":2648000},{"band":"$110k+","priceCents":3591000}]'::jsonb, 'Common Data Set 2024–25 and IPEDS (fall 2024 enrollment, 2025–26 cost). Deadlines and test policies verified against institution websites.', 'sourced')
