values ((select id from public.colleges where slug = 'umich'), '500 S State St, Ann Arbor, MI 48109', 1817, 'City', 'Michigan pairs a very large undergraduate population with a genuine college town — Ann Arbor''s downtown begins where campus ends, which is unusual at this scale. Nineteen schools and colleges admit undergraduates, and the Residential College and Honors Program exist specifically to make a 33,000-student institution feel navigable. Out-of-state admission is materially more competitive than in-state, and the cost gap is among the widest of any public flagship.', '11:1', 82, 93, 97, 1436400, '1350–1530', '31–34', '3.85–4.00', true, array['Computer Science', 'Business Administration', 'Economics', 'Psychology', 'Information Science']::text[], '{"undergrads":33730,"totalStudents":52230,"fullTimeUndergradPct":97,"retentionPct":97,"gender":{"femalePct":51,"malePct":49},"ethnicity":[{"group":"White","pct":54},{"group":"Asian","pct":17},{"group":"Hispanic/Latino","pct":8},{"group":"International","pct":8},{"group":"Two or more races","pct":5},{"group":"Black or African American","pct":4},{"group":"Unknown or other","pct":4}],"source":"IPEDS Fall Enrollment 2024–25 and Common Data Set section B. Percentages are rounded and may not total exactly 100."}'::jsonb, '{"essay":"Required","testing":"Optional","subjectTests":"Not accepted","interview":"Not accepted","note":"Common App essay plus a Michigan community supplement. Test optional through fall 2027 entry; no interviews at any stage."}'::jsonb, '[{"band":"Under $30k","priceCents":421000},{"band":"$30k–48k","priceCents":698000},{"band":"$48k–75k","priceCents":1372000},{"band":"$75k–110k","priceCents":2146000},{"band":"$110k+","priceCents":2834000}]'::jsonb, 'Common Data Set 2024–25 and IPEDS (fall 2024 enrollment, 2025–26 cost). Deadlines and test policies verified against institution websites.', 'sourced')
