values ((select id from public.colleges where slug = 'ut-austin'), '110 Inner Campus Drive, Austin, TX 78712', 1883, 'City', 'UT Austin admits by major, and that single fact drives most of the strategy around it: admission to Computer Science or McCombs is dramatically more selective than admission to the university at large, and internal transfer is not a reliable fallback. Texas residents in the top 6% of their high school class receive automatic admission to the university, though not to a specific program. The campus sits directly north of downtown Austin.', '18:1', 74, 89, 96, 1441600, '1240–1470', '27–33', '3.72–4.00', true, array['Computer Science', 'Biology', 'Finance', 'Mechanical Engineering', 'Communication']::text[], '{"undergrads":42444,"totalStudents":54644,"fullTimeUndergradPct":95,"retentionPct":96,"gender":{"femalePct":53,"malePct":47},"ethnicity":[{"group":"White","pct":34},{"group":"Hispanic/Latino","pct":27},{"group":"Asian","pct":22},{"group":"International","pct":6},{"group":"Black or African American","pct":5},{"group":"Two or more races","pct":4},{"group":"Unknown or other","pct":2}],"source":"IPEDS Fall Enrollment 2024–25 and Common Data Set section B. Percentages are rounded and may not total exactly 100."}'::jsonb, '{"essay":"Required","testing":"Required","subjectTests":"Not accepted","interview":"Conditional","note":"Testing is required again for fall 2026 entry. Auditions or portfolio reviews are required by Fine Arts, Architecture and a handful of other majors, and nothing else interviews."}'::jsonb, '[{"band":"Under $30k","priceCents":524000},{"band":"$30k–48k","priceCents":811000},{"band":"$48k–75k","priceCents":1493000},{"band":"$75k–110k","priceCents":2087000},{"band":"$110k+","priceCents":2564000}]'::jsonb, 'Common Data Set 2024–25 and IPEDS (fall 2024 enrollment, 2025–26 cost). Deadlines and test policies verified against institution websites.', 'sourced')
