values ((select id from public.colleges where slug = 'nyu'), '70 Washington Square S, New York, NY 10012', 1831, 'City', 'NYU has no walled campus — its buildings are distributed through Greenwich Village, and the city functions as the campus. Undergraduates apply to one of several distinct schools (CAS, Stern, Tisch, Tandon, Gallatin), each with its own admissions profile and culture. Financial aid is the most common friction point: NYU does not meet full demonstrated need for all admitted students, and families should model cost before the list is finalized.', '8:1', 79, 88, 94, 2311200, '1450–1560', '33–35', '3.75–4.00', true, array['Liberal Arts', 'Business', 'Computer Science', 'Drama', 'Economics']::text[], '{"undergrads":29401,"totalStudents":59301,"fullTimeUndergradPct":94,"retentionPct":94,"gender":{"femalePct":60,"malePct":40},"ethnicity":[{"group":"White","pct":24},{"group":"International","pct":22},{"group":"Asian","pct":21},{"group":"Hispanic/Latino","pct":16},{"group":"Black or African American","pct":8},{"group":"Two or more races","pct":6},{"group":"Unknown or other","pct":3}],"source":"IPEDS Fall Enrollment 2024–25 and Common Data Set section B. Percentages are rounded and may not total exactly 100."}'::jsonb, '{"essay":"Required","testing":"Optional","subjectTests":"Not accepted","interview":"Conditional","note":"Test optional, with a wide menu of accepted substitutes including IB and AP. Tisch and Steinhardt require an artistic review — audition or portfolio — which the rest of the university does not."}'::jsonb, '[{"band":"Under $30k","priceCents":2134000},{"band":"$30k–48k","priceCents":2487000},{"band":"$48k–75k","priceCents":3126000},{"band":"$75k–110k","priceCents":4018000},{"band":"$110k+","priceCents":5293000}]'::jsonb, 'Common Data Set 2024–25 and IPEDS (fall 2024 enrollment, 2025–26 cost). Deadlines and test policies verified against institution websites.', 'sourced')
