-- University of Washington

update public.colleges set aka = array['UW Seattle', 'UW', 'U Dub']::text[]
where slug = 'uw-seattle' and aka = '{}'::text[];

insert into public.college_profile_facts (college_id, address, founded, campus_setting, overview, student_faculty_ratio, graduation_rate_4yr, graduation_rate_6yr, retention_rate, room_and_board_cents, sat_range, act_range, gpa_range, common_app, popular_majors, student_life, admission_requirements, net_price_by_income, source_note, provenance)
values ((select id from public.colleges where slug = 'uw-seattle'), '1410 NE Campus Parkway, Seattle, WA 98195', 1861, 'City', 'UW admits most undergraduates to the university rather than to a major, then runs competitive secondary admission into Computer Science, Engineering and Business — a structure that catches families by surprise if nobody explains it early. The Seattle campus is walkable and sits on Union Bay, ten minutes from downtown by light rail. Direct-to-major admission exists for the strongest applicants and is worth targeting explicitly.', '19:1', 68, 84, 94, 1615800, '1240–1470', '28–33', '3.72–3.98', false, array['Computer Science', 'Biology', 'Business', 'Psychology', 'Bioengineering']::text[], '{"undergrads":36872,"totalStudents":53272,"fullTimeUndergradPct":93,"retentionPct":94,"gender":{"femalePct":53,"malePct":47},"ethnicity":[{"group":"White","pct":35},{"group":"Asian","pct":27},{"group":"International","pct":14},{"group":"Hispanic/Latino","pct":10},{"group":"Two or more races","pct":8},{"group":"Black or African American","pct":3},{"group":"Unknown or other","pct":3}],"source":"IPEDS Fall Enrollment 2024–25 and Common Data Set section B. Percentages are rounded and may not total exactly 100."}'::jsonb, '{"essay":"Required","testing":"Optional","subjectTests":"Not accepted","interview":"Not accepted","note":"Two written responses on the Washington application carry real weight in holistic review. No interviews, and no testing requirement."}'::jsonb, '[{"band":"Under $30k","priceCents":748000},{"band":"$30k–48k","priceCents":993000},{"band":"$48k–75k","priceCents":1624000},{"band":"$75k–110k","priceCents":2187000},{"band":"$110k+","priceCents":2651000}]'::jsonb, 'Common Data Set 2024–25 and IPEDS (fall 2024 enrollment, 2025–26 cost). Deadlines and test policies verified against institution websites.', 'sourced')
on conflict (college_id) do nothing;

insert into public.college_admitted_profiles (college_id, axes, rating_kind, note)
values ((select id from public.colleges where slug = 'uw-seattle'), '[{"label":"Grades","value":86},{"label":"Testing","value":78},{"label":"Rigor","value":83},{"label":"Extracurriculars","value":77},{"label":"Essays","value":78}]'::jsonb, 'meridies-curated', 'A curated static Meridies rating: the composite shape of admitted applicants, on the same five axes as a student''s own polygon so the two can be laid over each other. Proprietary, not a federal statistic, and not a prediction of any individual outcome.')
