values ((select id from public.colleges where slug = 'caltech'), '1200 E California Blvd, Pasadena, CA 91125', 1891, 'Suburban', 'Caltech is the smallest institution here by an order of magnitude — roughly a thousand undergraduates — and every one of them completes the same demanding core in mathematics, physics, chemistry and biology regardless of major. First-year grades are pass/fail. The honor code governs everything including take-home exams, and the eight residential Houses, not clubs, are the center of social life. It suits a narrow kind of student extremely well.', '3:1', 82, 93, 97, 2022600, '1530–1590', '35–36', '3.97–4.00', true, array['Computer Science', 'Physics', 'Electrical Engineering', 'Mechanical Engineering', 'Chemistry']::text[], '{"undergrads":1024,"totalStudents":2424,"fullTimeUndergradPct":100,"retentionPct":97,"gender":{"femalePct":45,"malePct":55},"ethnicity":[{"group":"Asian","pct":33},{"group":"White","pct":24},{"group":"Hispanic/Latino","pct":16},{"group":"International","pct":14},{"group":"Two or more races","pct":7},{"group":"Black or African American","pct":3},{"group":"Unknown or other","pct":3}],"source":"IPEDS Fall Enrollment 2024–25 and Common Data Set section B. Percentages are rounded and may not total exactly 100."}'::jsonb, '{"essay":"Required","testing":"Required","subjectTests":"Not accepted","interview":"Not accepted","note":"Testing is required again after the moratorium. Caltech ended alumni interviews entirely rather than run them unevenly, so no applicant is at a coverage disadvantage."}'::jsonb, '[{"band":"Under $30k","priceCents":312000},{"band":"$30k–48k","priceCents":487000},{"band":"$48k–75k","priceCents":1143000},{"band":"$75k–110k","priceCents":2294000},{"band":"$110k+","priceCents":3978000}]'::jsonb, 'Common Data Set 2024–25 and IPEDS (fall 2024 enrollment, 2025–26 cost). Deadlines and test policies verified against institution websites.', 'sourced')
on conflict (college_id) do nothing;

